print(f"{'n':>6}{'dec':>10}{'hex':>10}{'bin':>16}{'oct':>8}{'sci':>14}")
for n in (0, 1, 7, 255, 1024, 65535, 2 ** 31, 2 ** 40 + 5, 10 ** 15, 10 ** 20, 2 ** 70):
    print(f"{n:>6.0e}{n:>10,}{n:>10x}{n:>16b}"[:60], f"{n:o}", f"{n:e}", f"{n:.3g}", f"{float(n):.2f}"[:25], f"{n:#x}", f"{-n:#b}"[:20], f"{n:_}", f"{n:+d}"[:12], f"{n:010d}"[:12])
for x in (0.5, 1.5, 2.5, 1234.5678, 1e-5, 12345678.9, 0.000123456, 99.99, 100.0, 1 / 3):
    print(f"{x:.1f} {x:.0f} {x:8.3f} {x:<8.1f}| {x:+.2e} {x:g} {x:.3g} {x:10.4g}| {x:%} {x:.0%} {x:,.2f} {x:012.4f} {x!r} {round(x, 1)} {round(x)}")
for p in (0, 1, 2, 5, 10, 15, 17, 20):
    print(p, f"{1/3:.{p}f}", f"{2/3:.{p}e}", f"{1e10/3:.{p}g}")
